messages.content:
[tool error]
{
  "ok": false,
  "name": "create_viewport",
  "error": {
    "type": "invalid_params",
    "message": "Additional properties are not allowed ('model_width_in' was unexpected)",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "sheet": {
          "type": "string",
          "minLength": 1
        },
        "center_paper": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "viewport center on the sheet, inches"
        },
        "width_in": {
          "type": "number",
          "exclusiveMinimum": 0
        },
        "height_in": {
          "type": "number",
          "exclusiveMinimum": 0
        },
        "model_center": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "model-space point (feet) shown at the viewport center"
        },
        "feet_per_inch": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "plot scale: 1\"=50' -> 50"
        },
        "rotation_deg": {
          "type": "number",
          "description": "view twist: model appears rotated CCW by this angle on the sheet"
        }
      },
      "required": [
        "sheet",
        "center_paper",
        "width_in",
        "height_in",
        "model_center",
        "feet_per_inch"
      ],
      "additionalProperties": false
    },
    "example": {
      "sheet": "P-201",
      "center_paper": [
        17.0,
        12.0
      ],
      "width_in": 31.0,
      "height_in": 18.0,
      "model_center": [
        4800.0,
        7450.0
      ],
      "feet_per_inch": 50.0,
      "rotation_deg": 0.0
    }
  },
  "warnings": []
}
